export const voiceSchema = {
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "OPM.js canonical voice v6",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "name",
    "algorithm",
    "feedback",
    "modIndex",
    "lfo",
    "ops"
  ],
  "properties": {
    "version": {
      "const": 6
    },
    "name": {
      "type": "string",
      "pattern": "^[a-zA-Z0-9_-]{1,64}$"
    },
    "algorithm": {
      "type": "integer",
      "minimum": 0,
      "maximum": 7
    },
    "feedback": {
      "type": "integer",
      "minimum": 0,
      "maximum": 7
    },
    "modIndex": {
      "type": "number",
      "minimum": 0,
      "maximum": 16
    },
    "pitchEnvelope": {
      "type": "object",
      "additionalProperties": false,
      "required": ["a", "d", "r", "initial", "peak", "sustain", "final"],
      "properties": {
        "a": { "type": "number", "minimum": 0, "maximum": 10 },
        "d": { "type": "number", "minimum": 0, "maximum": 10 },
        "r": { "type": "number", "minimum": 0, "maximum": 10 },
        "initial": { "type": "number", "minimum": -4800, "maximum": 4800 },
        "peak": { "type": "number", "minimum": -4800, "maximum": 4800 },
        "sustain": { "type": "number", "minimum": -4800, "maximum": 4800 },
        "final": { "type": "number", "minimum": -4800, "maximum": 4800 }
      }
    },
    "lfo": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "rate",
        "amDepth",
        "pmDepth",
        "waveform"
      ],
      "properties": {
        "delay": { "type": "number", "minimum": 0, "maximum": 10, "default": 0 },
        "sync": { "type": "string", "enum": ["note", "global"], "default": "note" },
        "phase": { "type": "number", "minimum": 0, "maximum": 1, "default": 0 },
        "amTargets": {
          "type": "array", "minItems": 4, "maxItems": 4,
          "items": { "type": "number", "minimum": 0, "maximum": 1 },
          "description": "Per-operator AM depth multipliers; omitted means all one."
        },
        "pmTargets": {
          "type": "array", "minItems": 4, "maxItems": 4,
          "items": { "type": "number", "minimum": 0, "maximum": 1 },
          "description": "Per-operator PM depth multipliers; omitted means all one."
        },
        "waveform": {
          "type": "string",
          "enum": ["sine", "triangle", "saw", "square"]
        },
        "rate": {
          "type": "number",
          "minimum": 0,
          "maximum": 20
        },
        "amDepth": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "pmDepth": {
          "type": "number",
          "minimum": 0,
          "maximum": 1200
        }
      }
    },
    "ops": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "ratio",
          "level",
          "detune",
          "adsr"
        ],
        "properties": {
          "frequency": {
            "type": "number", "minimum": 1, "maximum": 20000,
            "description": "Fixed Hz before detune, live pitch, pitch envelope and LFO PM; overrides note times ratio."
          },
          "rateKeyScale": {
            "type": "number", "minimum": 0, "maximum": 4,
            "description": "Multiply ADSR seconds by 2^(-rateKeyScale*(note-60)/12), capped at 10 seconds."
          },
          "velocitySensitivity": {
            "type": "number",
            "minimum": 0,
            "maximum": 48,
            "description": "Operator attenuation in dB at velocity zero; omitted means zero."
          },
          "keyScale": {
            "type": "object",
            "additionalProperties": false,
            "required": ["breakpoint", "leftDbPerOctave", "rightDbPerOctave"],
            "properties": {
              "breakpoint": { "type": "integer", "minimum": 0, "maximum": 127 },
              "leftDbPerOctave": { "type": "number", "minimum": 0, "maximum": 24 },
              "rightDbPerOctave": { "type": "number", "minimum": 0, "maximum": 24 }
            }
          },
          "ratio": {
            "type": "number",
            "minimum": 0.125,
            "maximum": 32
          },
          "level": {
            "type": "number",
            "minimum": 0,
            "maximum": 1
          },
          "detune": {
            "type": "number",
            "minimum": -1200,
            "maximum": 1200
          },
          "adsr": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "a",
              "d",
              "s",
              "r"
            ],
            "properties": {
              "a": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              },
              "d": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              },
              "s": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "r": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              }
            }
          }
        }
      }
    }
  }
};
